#requires -Version 7.0
[CmdletBinding()]
param(
    [int]$PilotSize = 24,
    [int]$ValidationSize = 100,
    [int]$ConcurrencyPerModel = 2
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

$ToolRoot = Split-Path -Parent $PSCommandPath
$StatePath = Join-Path $ToolRoot 'state.json'
$BaseControllerCommit = 'd3f5fba30e711b876b713990ac9b15c51828943d'
$BaseControllerRepoPath = 'tools/gpi-hub-migration/Invoke-GPIHub-V117-ModelBakeoff-REV2.ps1'
$ExpectedBaseControllerBlob = '29b2105cd5eb461320c798879af3a722e97ac040'

function Require {
    param([bool]$Condition,[string]$Message)
    if (-not $Condition) { throw $Message }
}

function Get-GitText {
    param([string]$Repo,[string]$Ref,[string]$RepoPath)
    $spec = "{0}:{1}" -f $Ref,$RepoPath
    $lines = & git.exe -C $Repo show $spec
    $code = $LASTEXITCODE
    Require ($code -eq 0) "Could not read $RepoPath from $Ref."
    return ((@($lines) | ForEach-Object { [string]$_ }) -join "`n") -replace "`r",''
}

function FromB64 {
    param([Parameter(Mandatory)][string]$Value)
    return [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value))
}

Require (Test-Path -LiteralPath $StatePath -PathType Leaf) "Direct confirmation state missing: $StatePath"
Require ($null -ne (Get-Command git.exe -ErrorAction SilentlyContinue)) 'git.exe unavailable.'
Require ($null -ne (Get-Command pwsh.exe -ErrorAction SilentlyContinue)) 'pwsh.exe unavailable.'

$State = Get-Content -LiteralPath $StatePath -Raw | ConvertFrom-Json -Depth 80
$OperationalRoot = [string]$State.local.operational_root
Require (Test-Path -LiteralPath $OperationalRoot -PathType Container) "Operational repo missing: $OperationalRoot"

$baseSpec = "{0}:{1}" -f $BaseControllerCommit,$BaseControllerRepoPath
$baseBlob = (& git.exe -C $OperationalRoot rev-parse $baseSpec).Trim()
Require ($LASTEXITCODE -eq 0) 'Could not resolve valid REV2 base controller blob.'
Require ($baseBlob -ceq $ExpectedBaseControllerBlob) "REV2 base controller blob drift: $baseBlob"

$Raw = Get-GitText -Repo $OperationalRoot -Ref $BaseControllerCommit -RepoPath $BaseControllerRepoPath
$InvokeOld = FromB64 'JiBwd3NoLmV4ZSAtTm9Qcm9maWxlIC1FeGVjdXRpb25Qb2xpY3kgQnlwYXNzIC1GaWxlICRHZW5lcmF0ZWRDb250cm9sbGVyIGAKICAgIC1QaWxvdFNpemUgJFBpbG90U2l6ZSBgCiAgICAtVmFsaWRhdGlvblNpemUgJFZhbGlkYXRpb25TaXplIGAKICAgIC1Db25jdXJyZW5jeVBlck1vZGVsICRDb25jdXJyZW5jeVBlck1vZGVsCmV4aXQgJExBU1RFWElUQ09ERQ=='
$InvokeNew = FromB64 ''
Require ($Raw.Contains($InvokeOld)) 'Direct confirmation REV2 final invocation anchor missing.'
$Raw = $Raw.Replace($InvokeOld,$InvokeNew)

$Generated = Join-Path $ToolRoot 'Invoke-GPIHub-V117-ModelSelection-Confirm-Frozen40-REV3-Direct-Generated.ps1'
Set-Content -LiteralPath $Generated -Value $Raw -Encoding utf8 -NoNewline

$tokens = $null
$errors = $null
[void][System.Management.Automation.Language.Parser]::ParseFile($Generated,[ref]$tokens,[ref]$errors)
if (@($errors).Count -gt 0) {
    $msg = (@($errors) | ForEach-Object { "line=$($_.Extent.StartLineNumber): $($_.Message)" }) -join '; '
    throw "Direct confirmation generated builder parse failed: $msg"
}

Write-Host 'V117_CONFIRM_REV3_DIRECT_BASE_REV2_BLOB=29b2105cd5eb461320c798879af3a722e97ac040' -ForegroundColor Green
Write-Host 'V117_CONFIRM_REV3_DIRECT_NO_REV3_DETACHED_TEMPLATE_DEPENDENCY=PASS' -ForegroundColor Green
Write-Host 'V117_CONFIRM_REV3_DIRECT_BUILDER_PARSE=PASS' -ForegroundColor Green
Write-Host 'V117_CONFIRM_REV3_DIRECT_SELECTION_LOGIC=REV2_RELIABILITY_AWARE' -ForegroundColor Green
Write-Host 'V117_CONFIRM_REV3_DIRECT_FROZEN40_EXCLUSION=EXACT_PRESELECTION' -ForegroundColor Green
Write-Host 'V117_CONFIRM_REV3_DIRECT_PRODUCTION_MUTATION=NONE' -ForegroundColor Green
Write-Host "V117_CONFIRM_REV3_DIRECT_GENERATED=$Generated"

& pwsh.exe -NoProfile -ExecutionPolicy Bypass -File $Generated `
    -PilotSize $PilotSize `
    -ValidationSize $ValidationSize `
    -ConcurrencyPerModel $ConcurrencyPerModel
exit $LASTEXITCODE
